DO $before$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN
  -- The fixture moves to the time it started, and goes live (the fixture route, by the director of sport).
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE match SET starts_at = date_bin('5 minutes', (now() - make_interval(secs => 5220)), timestamptz '2000-01-01') WHERE id = m;
  UPDATE match SET status = 'live' WHERE id = m;
  PERFORM app_session_begin((ids->>'transport.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE trip SET depart_at = (SELECT mt.starts_at - interval '75 minutes' FROM match mt WHERE mt.id = m),
                  return_at = (SELECT mt.starts_at + interval '4 hours' FROM match mt WHERE mt.id = m) WHERE match_id = m;
  PERFORM app_session_begin((ids->>'scorer1.wes@example.invalid')::uuid, 'demo-season-pad-wes', NULL, NULL);
  INSERT INTO match_toss (match_id, school_id, won_by, decision, called_by, called_at)
  VALUES (m, match_school(m), 'home', 'bat', app_user_id(), now())
  ON CONFLICT (match_id) DO UPDATE SET won_by = excluded.won_by, decision = excluded.decision, called_by = excluded.called_by, called_at = excluded.called_at;
  SELECT x.fixed AS ok, x.reason INTO r FROM match_conditions_fix(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The playing conditions could not be fixed on 1xi-1107: %. Nothing was changed.', r.reason; END IF;
END $before$;
