RESET ROLE;
DO $check$
BEGIN
  IF (SELECT count(*) FROM ball_event WHERE match_id = 'de5e0000-0000-4000-a000-000000000201') <> 215 THEN
    RAISE EXCEPTION 'The live match is incomplete. Rolled back.'; END IF;
END $check$;
COMMIT;
